namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    [MinLength(10, ErrorMessage = "Please provide more detail for ingredients.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    [MinLength(10, ErrorMessage = "Please provide more detail for the steps.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals & sandwiches", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats & baking", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites & appetizers", Icon = "🧀" },
            new() { Name = "Drinks", Description = "Smoothies, cocktails & more", Icon = "🍹" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt\nButter for cooking",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a buttered pan over medium heat.\n5. Pour batter and cook until bubbles form, then flip.\n6. Serve with maple syrup and fresh berries.",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice\nOptional: poached egg",
                Steps = "1. Toast the bread until golden and crispy.\n2. Mash the avocado with lemon juice, salt, and pepper.\n3. Spread avocado on toast.\n4. Sprinkle red pepper flakes.\n5. Top with a poached egg if desired.",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop the romaine lettuce.\n2. Toss with Caesar dressing.\n3. Add croutons and shaved parmesan.\n4. Top with grilled chicken if desired.\n5. Serve immediately.",
                AverageRating = 4.0, RatingCount = 6
            },
            new()
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Dinner",
                Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n1 cup pecorino cheese\nBlack pepper\nSalt",
                Steps = "1. Cook pasta in salted boiling water.\n2. Fry pancetta until crispy.\n3. Whisk egg yolks with grated cheese and pepper.\n4. Drain pasta, reserving some water.\n5. Toss hot pasta with pancetta off heat.\n6. Stir in egg mixture quickly, adding pasta water as needed.\n7. Serve immediately with extra cheese.",
                AverageRating = 4.8, RatingCount = 20
            },
            new()
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n3 eggs\n100g sugar\n50g flour\nButter and cocoa for ramekins",
                Steps = "1. Preheat oven to 220°C (425°F).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until fluffy.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake for 10-12 minutes.\n7. Invert onto plates and serve immediately.",
                AverageRating = 4.9, RatingCount = 15
            },
            new()
            {
                Id = 6, Title = "Guacamole", Category = "Snacks",
                Ingredients = "3 ripe avocados\n1 lime\n1/2 red onion\n2 tomatoes\nFresh cilantro\nSalt\nJalapeño (optional)",
                Steps = "1. Halve and pit the avocados.\n2. Mash to desired consistency.\n3. Dice onion and tomatoes finely.\n4. Mix in lime juice, onion, tomatoes, and cilantro.\n5. Season with salt.\n6. Add diced jalapeño for heat.\n7. Serve with tortilla chips.",
                AverageRating = 4.3, RatingCount = 9
            },
            new()
            {
                Id = 7, Title = "Mango Smoothie", Category = "Drinks",
                Ingredients = "2 ripe mangoes\n1 cup yogurt\n1/2 cup milk\n1 tbsp honey\nIce cubes",
                Steps = "1. Peel and chop the mangoes.\n2. Add all ingredients to a blender.\n3. Blend until smooth.\n4. Pour into glasses.\n5. Garnish with mint if desired.",
                AverageRating = 4.1, RatingCount = 5
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalRating = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalRating + rating) / recipe.RatingCount;
    }
}

