@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
              @onmouseover="() => _hoveredStar = star"
              @onmouseout="() => _hoveredStar = 0"
              @onclick="() => SubmitRating(star)">
            ★
        </span>
    }
    <span class="rating-text">
        @if (_submitted)
        {
            <span>Thanks for rating!</span>
        }
        else if (AverageRating > 0)
        {
            <span>@AverageRating.ToString("F1") (@RatingCount ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private async Task SubmitRating(int rating)
    {
        _selectedStar = rating;
        _submitted = true;
        await OnRated.InvokeAsync(rating);
    }
}

.star-rating {
    display: inline-flex;
    align-items: center;
    gap: 2px;
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star.hovered,
.star.selected {
    color: #f5a623;
}

.rating-text {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #666;
}

@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

