+        @foreach (var recipe in _recipes)
+        {
+            <a href="/recipe/@recipe.Id" class="recipe-card">
+                <h3>@recipe.Title</h3>
+                <div class="recipe-meta">
+                    <span class="stars">@GetStarsDisplay(recipe.AverageRating)</span>
+                    <span class="rating-count">(@recipe.RatingCount ratings)</span>
+                </div>
+            </a>
+        }
+    </div>
+}
+
+@code {
+    [Parameter] public string CategoryName { get; set; } = string.Empty;
+    [Inject] private RecipeService RecipeService { get; set; } = default!;
+
+    private List<Recipe> _recipes = [];
+    private RecipeCategory? _category;
+
+    protected override void OnInitialized()
+    {
+        _category = RecipeService.GetCategories()
+            .FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
+        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
+    }
+
+    private static string GetStarsDisplay(double rating)
+    {
+        int full = (int)Math.Round(rating);
+        return new string('★', full) + new string('☆', 5 - full);
+    }
+}
+

