@page "/recipe/{RecipeId:int}"
@using RecipeCommunity.Components.Shared
@using RecipeCommunity.Models
@using RecipeCommunity.Services

<PageTitle>@(_recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (_recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/recipes/@_recipe.Category.ToLower()">@_recipe.Category</a> &rsaquo;
        <span>@_recipe.Title</span>
    </nav>

    <article class="recipe-detail">
        <h1>@_recipe.Title</h1>

        <div class="rating-section">
            <StarRating RecipeId="@_recipe.Id"
                        AverageRating="@_recipe.AverageRating"
                        RatingCount="@_recipe.RatingCount"
                        OnRated="HandleRating" />
        </div>

        <section class="recipe-section">
            <h2>🥘 Ingredients</h2>
            <div class="ingredients">
                @foreach (var line in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <div class="ingredient-item">@line.Trim()</div>
                }
            </div>
        </section>

        <section class="recipe-section">
            <h2>📝 Steps</h2>
            <div class="steps">
                @foreach (var line in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <div class="step-item">@line.Trim()</div>
                }
            </div>
        </section>
    </article>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void HandleRating(int rating)
    {
        RecipeService.RateRecipe(RecipeId, rating);
    }
}

