toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo; <span>Submit Recipe</span>
</nav>

<h1>📤 Submit a Recipe</h1>
<p class="subtitle">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="success-message">
        <h2>✅ Recipe Submitted!</h2>
        <p>Thank you for sharing "<strong>@_model.Title</strong>" with the community.</p>
        <a href="/">← Back to Home</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" class="recipe-form" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" rows="6"
                           placeholder="List each ingredient on a new line..." />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="form-group">
            <label for="steps">Preparation Steps</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" rows="8"
                           placeholder="Describe each step on a new line..." />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission _model = new();
    private List<RecipeCategory> _categories = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }
}

.breadcrumb {
    margin-bottom: 1rem;
    font-size: 0.9rem;
    color: #666;
}

.breadcrumb a {
    color: #667eea;
    text-decoration: none;
}

.subtitle {
    color: #666;
    margin-bottom: 1.5rem;
}

.recipe-form {
    max-width: 600px;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.4rem;
    color: #333;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 1rem;
    font-family: inherit;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.btn-submit {
    padding: 0.75rem 2rem;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    transition: opacity 0.2s;
}

.btn-submit:hover {
    opacity: 0.9;
}

.success-message {
    padding: 2rem;
    background: #f0fff4;
    border: 1px solid #c6f6d5;
    border-radius: 8px;
    text-align: center;
}

.success-message h2 {
    color: #2f855a;
}

.success-message a {
    color: #667eea;
    text-decoration: none;
}

::deep .validation-message {
    color: #e53e3e;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

::deep .validation-errors {
    color: #e53e3e;
    margin-bottom: 1rem;
}

