toolArgs.new_str:
@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="hero">
    <h1>🍳 Recipe Community</h1>
    <p>Discover, share, and rate delicious recipes from home cooks around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in _categories)
    {
        <a href="/recipes/@category.Name.ToLower()" class="category-card">
            <span class="category-icon">@category.Icon</span>
            <h3>@category.Name</h3>
            <p>@category.Description</p>
        </a>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Models.RecipeCategory> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }
}

